// n8n Code Node: Convert Competitor Analysis JSON to Notion Blocks
// Run mode: Run Once for All Items

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Create Notion blocks array
  const notionBlocks = [];

  // ========================================
  // PAGE TITLE (Heading 1)
  // ========================================
  notionBlocks.push({
    object: "block",
    type: "heading_1",
    heading_1: {
      rich_text: [{
        type: "text",
        text: {
          content: "🎯 IG Research Report"
        },
        annotations: {
          bold: true,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: "default"
        }
      }],
      color: "blue",
      is_toggleable: false
    }
  });

  // Add date
  notionBlocks.push({
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{
        type: "text",
        text: {
          content: `Analysis Date: ${new Date().toLocaleDateString()}`
        },
        annotations: {
          bold: false,
          italic: true,
          strikethrough: false,
          underline: false,
          code: false,
          color: "gray"
        }
      }],
      color: "default"
    }
  });

  // Divider
  notionBlocks.push({
    object: "block",
    type: "divider",
    divider: {}
  });

  // ========================================
  // KEY TAKEAWAY CALLOUT
  // ========================================
  notionBlocks.push({
    object: "block",
    type: "callout",
    callout: {
      rich_text: [{
        type: "text",
        text: {
          content: data.key_takeaway || "No key takeaway provided"
        },
        annotations: {
          bold: false,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: "default"
        }
      }],
      icon: {
        emoji: "💡"
      },
      color: "blue_background"
    }
  });

  // Divider
  notionBlocks.push({
    object: "block",
    type: "divider",
    divider: {}
  });

  // ========================================
  // TOP COMPETITOR VIDEOS SECTION
  // ========================================
  notionBlocks.push({
    object: "block",
    type: "heading_2",
    heading_2: {
      rich_text: [{
        type: "text",
        text: {
          content: "🏆 Top Performing Videos"
        },
        annotations: {
          bold: true,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: "default"
        }
      }],
      color: "purple",
      is_toggleable: false
    }
  });

  // Process each video
  if (data.top_competitor_videos && Array.isArray(data.top_competitor_videos)) {
    data.top_competitor_videos.forEach((video, index) => {
      // Video toggle (collapsible section)
      const videoChildren = [];

      // Metadata (Creator, Views, Date)
      videoChildren.push({
        object: "block",
        type: "paragraph",
        paragraph: {
          rich_text: [{
            type: "text",
            text: {
              content: `Creator: ${video.creator}`
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "gray"
            }
          }],
          color: "default"
        }
      });

      videoChildren.push({
        object: "block",
        type: "paragraph",
        paragraph: {
          rich_text: [{
            type: "text",
            text: {
              content: `Views: ${video.views.toLocaleString()}`
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "gray"
            }
          }],
          color: "default"
        }
      });

      // Format date as MM-DD-YYYY
      const dateParts = video.posted_date.split('-');
      const formattedDate = `${dateParts[1]}-${dateParts[2]}-${dateParts[0]}`;

      videoChildren.push({
        object: "block",
        type: "paragraph",
        paragraph: {
          rich_text: [{
            type: "text",
            text: {
              content: `Posted: ${formattedDate}`
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "gray"
            }
          }],
          color: "default"
        }
      });

      // URL
      videoChildren.push({
        object: "block",
        type: "paragraph",
        paragraph: {
          rich_text: [
            {
              type: "text",
              text: {
                content: "Watch Video",
                link: {
                  url: video.url
                }
              },
              annotations: {
                bold: false,
                italic: false,
                strikethrough: false,
                underline: true,
                code: false,
                color: "blue"
              }
            },
            {
              type: "text",
              text: {
                content: " 👈"
              },
              annotations: {
                bold: false,
                italic: false,
                strikethrough: false,
                underline: false,
                code: false,
                color: "default"
              }
            }
          ],
          color: "default"
        }
      });

      // Why it worked (callout)
      videoChildren.push({
        object: "block",
        type: "callout",
        callout: {
          rich_text: [{
            type: "text",
            text: {
              content: video.why_it_worked
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "default"
            }
          }],
          icon: {
            emoji: "✅"
          },
          color: "green_background"
        }
      });

      // Main toggle for the video
      notionBlocks.push({
        object: "block",
        type: "toggle",
        toggle: {
          rich_text: [
            {
              type: "text",
              text: {
                content: `#${video.rank} - `
              },
              annotations: {
                bold: true,
                italic: false,
                strikethrough: false,
                underline: false,
                code: false,
                color: "default"
              }
            },
            {
              type: "text",
              text: {
                content: video.hook
              },
              annotations: {
                bold: false,
                italic: false,
                strikethrough: false,
                underline: false,
                code: false,
                color: "default"
              }
            }
          ],
          color: "default",
          children: videoChildren
        }
      });
    });
  }

  // Divider
  notionBlocks.push({
    object: "block",
    type: "divider",
    divider: {}
  });

  // ========================================
  // WINNING PATTERNS SECTION
  // ========================================
  notionBlocks.push({
    object: "block",
    type: "heading_2",
    heading_2: {
      rich_text: [{
        type: "text",
        text: {
          content: "🧩 Winning Patterns"
        },
        annotations: {
          bold: true,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: "default"
        }
      }],
      color: "orange",
      is_toggleable: false
    }
  });

  // Process each pattern
  if (data.winning_patterns && Array.isArray(data.winning_patterns)) {
    data.winning_patterns.forEach((pattern, index) => {
      const patternChildren = [];

      // Explanation (as green callout)
      patternChildren.push({
        object: "block",
        type: "callout",
        callout: {
          rich_text: [{
            type: "text",
            text: {
              content: pattern.explanation
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "default"
            }
          }],
          icon: {
            emoji: "✅"
          },
          color: "green_background"
        }
      });

      // Main toggle (without number)
      notionBlocks.push({
        object: "block",
        type: "toggle",
        toggle: {
          rich_text: [{
            type: "text",
            text: {
              content: pattern.pattern_name
            },
            annotations: {
              bold: true,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: "default"
            }
          }],
          color: "default",
          children: patternChildren
        }
      });
    });
  }

  // Divider
  notionBlocks.push({
    object: "block",
    type: "divider",
    divider: {}
  });

  // ========================================
  // HOOK IDEAS SECTION
  // ========================================
  notionBlocks.push({
    object: "block",
    type: "heading_2",
    heading_2: {
      rich_text: [{
        type: "text",
        text: {
          content: "🪝 Hook Ideas"
        },
        annotations: {
          bold: true,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: "default"
        }
      }],
      color: "pink",
      is_toggleable: false
    }
  });

  // Process each hook
  if (data.hook_ideas && Array.isArray(data.hook_ideas)) {
    data.hook_ideas.forEach((hookIdea, index) => {
      // Numbered list item with inline code hook (yellow text)
      // and why it works as nested child
      notionBlocks.push({
        object: "block",
        type: "numbered_list_item",
        numbered_list_item: {
          rich_text: [{
            type: "text",
            text: {
              content: hookIdea.hook
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: true,
              color: "yellow"
            }
          }],
          color: "default",
          children: [
            {
              object: "block",
              type: "paragraph",
              paragraph: {
                rich_text: [{
                  type: "text",
                  text: {
                    content: hookIdea.why_it_works
                  },
                  annotations: {
                    bold: false,
                    italic: false,
                    strikethrough: false,
                    underline: false,
                    code: false,
                    color: "default"
                  }
                }],
                color: "default"
              }
            }
          ]
        }
      });
    });
  }

  // Return formatted blocks in the structure Notion expects
  results.push({
    json: {
      children: notionBlocks
    }
  });
}

return results;
